//! Collations: how text compares, sorts and groups (issue #13).
//!
//! `utf8mb4_0900_bin` uses MySQL's UTF-8 byte order and NO PAD semantics.
//! Legacy families use MariaDB 10.11 weight tables (`collation_data.rs`,
//! generated by `scripts/gen_collations.py`), with the differences below:
//!
//! * `utf8mb4_bin`: bytes as stored. Unlike MySQL's PAD SPACE `_bin`,
//!   trailing spaces count (`'a' <> 'a '`), as they always have in Tarn.
//! * `utf8mb4_general_ci`: one 16-bit weight per character (the upper-case
//!   letter without accents: `'é'` = `'E'`, `'ß'` = `'S'`); every character
//!   above U+FFFF weighs the same.
//! * `utf8mb4_unicode_ci`: UCA 4.0.0 primary weights, a sequence per
//!   character (`'ß'` = `'ss'`, `'æ'` = `'ae'`, ignorable control
//!   characters weigh nothing); CJK ideographs and unassigned code points
//!   get weights computed from the code point; characters above U+FFFF
//!   weigh the same.
//!
//! The `_ci` collations are PAD SPACE (trailing spaces do not count) or,
//! in their `_nopad_` variants, NO PAD. Two strings are equal when their
//! weight strings are equal, and order as their weight strings do: the
//! *key* of a string (`Collation::key`) is that weight string, big-endian,
//! without trailing space weights under PAD SPACE. Indexes on
//! case-insensitive columns are built on the keys (a weight field next to
//! the column, see catalog.rs), so the storage orders and compares exactly
//! as this module does. (MySQL orders a string ending in a character below
//! the space, such as a tab, before the same string without it; by keys it
//! comes after.)
//!
//! Other collation names map to the closest of these (see `from_name`);
//! the declared name is kept for display.

use crate::collation_data as data;
use bytes::Bytes;
use std::cmp::Ordering;
use std::sync::OnceLock;

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub enum Collation {
    /// utf8mb4_bin: bytes as stored, trailing spaces count.
    #[default]
    Utf8Bin,
    /// MySQL 8 utf8mb4_0900_bin: UTF-8 byte order and NO PAD.
    Utf8NoPad,
    /// utf8mb4_general_ci (pad) / utf8mb4_general_nopad_ci.
    General { pad: bool },
    /// utf8mb4_unicode_ci (pad) / utf8mb4_unicode_nopad_ci.
    Unicode { pad: bool },
    /// Binary strings (BINARY, VARBINARY, BLOB, X'..' literals): bytes.
    Binary,
}

/// MySQL's coercibility of a collation (lower wins when two collations
/// meet; COERCIBILITY() returns it).
pub mod coercibility {
    pub const EXPLICIT: u8 = 0;
    pub const IMPLICIT: u8 = 2;
    pub const SYSCONST: u8 = 3;
    pub const COERCIBLE: u8 = 4;
    pub const NUMERIC: u8 = 5;
    pub const IGNORABLE: u8 = 6;
}

/// The collation of a string-valued expression with its coercibility and
/// display name (the name it was declared with).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Derived {
    pub coll: Collation,
    pub coercibility: u8,
    pub name: String,
}

impl Derived {
    pub fn new(coll: Collation, coercibility: u8) -> Derived {
        Derived {
            coll,
            coercibility,
            name: coll.name().to_string(),
        }
    }
    pub fn named(name: &str, coercibility: u8) -> Option<Derived> {
        Some(Derived {
            coll: Collation::from_name(name)?,
            coercibility,
            name: name.to_ascii_lowercase(),
        })
    }
}

fn coercibility_name(c: u8) -> &'static str {
    match c {
        0 => "EXPLICIT",
        1 => "NONE",
        2 => "IMPLICIT",
        3 => "SYSCONST",
        4 => "COERCIBLE",
        5 => "NUMERIC",
        _ => "IGNORABLE",
    }
}

/// The collation two or more string operands meet in (MySQL's rules): the
/// lowest coercibility wins; at a tie, a binary string or a `_bin`
/// collation wins over the others, and two other collations are an error
/// (1267 for two operands, 1270 for more) when both are implicit or
/// explicit. None when no operand is a string.
pub fn aggregate(items: &[Option<Derived>], op: &str) -> tarn_common::SqlResult<Option<Derived>> {
    let strs: Vec<&Derived> = items.iter().flatten().collect();
    if strs.is_empty() {
        return Ok(None);
    }
    let best = strs.iter().map(|d| d.coercibility).min().unwrap();
    let tied: Vec<&&Derived> = strs.iter().filter(|d| d.coercibility == best).collect();
    // (a binary string literal is coercible: a column's collation wins over
    // it, ci_col = X'41' compares under the column's; X'61' = 'A' by bytes)
    if let Some(b) = tied.iter().find(|d| d.coll == Collation::Binary) {
        return Ok(Some((**b).clone()));
    }
    let first = tied[0];
    if tied.iter().all(|d| d.coll == first.coll) {
        return Ok(Some((*first).clone()));
    }
    if let Some(b) = tied
        .iter()
        .find(|d| matches!(d.coll, Collation::Utf8Bin | Collation::Utf8NoPad))
    {
        return Ok(Some((**b).clone()));
    }
    if best <= coercibility::IMPLICIT {
        let names: Vec<String> = strs
            .iter()
            .map(|d| format!("({},{})", d.name, coercibility_name(d.coercibility)))
            .collect();
        return Err(if strs.len() == 2 {
            tarn_common::SqlError::new(
                1267,
                "HY000",
                format!(
                    "Illegal mix of collations {} and {} for operation '{}'",
                    names[0], names[1], op
                ),
            )
        } else {
            tarn_common::SqlError::new(
                1270,
                "HY000",
                format!("Illegal mix of collations {} for operation '{}'", names.join(", "), op),
            )
        });
    }
    Ok(Some((*first).clone()))
}

impl Collation {
    /// The collation a name declares, or None if Tarn does not know it.
    /// Names of collations Tarn does not implement map to the closest one:
    /// `_bin`, `_cs` and `_as_cs` to utf8mb4_bin, MySQL 8's
    /// utf8mb4_0900_ai_ci to utf8mb4_unicode_nopad_ci (both NO PAD),
    /// other UCA-based `_ci` collations (unicode_520, uca1400, language
    /// variants) to utf8mb4_unicode_ci, and the remaining `_ci` ones
    /// (latin1_swedish_ci, ...) to utf8mb4_general_ci.
    pub fn from_name(name: &str) -> Option<Collation> {
        let n = name.trim().trim_matches('`').trim_matches('\'').to_ascii_lowercase();
        if n == "utf8mb4_0900_bin" {
            return Some(Collation::Utf8NoPad);
        }
        if n == "binary" {
            return Some(Collation::Binary);
        }
        let (cs, rest) = n.split_once('_')?;
        if !matches!(
            cs,
            "utf8mb4" | "utf8mb3" | "utf8" | "latin1" | "ascii" | "ucs2" | "utf16" | "utf32" | "uca1400"
        ) {
            return None;
        }
        // Every word of the name must be one MySQL or MariaDB collation
        // names use (collation family, UCA version, pad, language, level).
        const WORDS: &[&str] = &[
            "general",
            "unicode",
            "bin",
            "ci",
            "cs",
            "ai",
            "as",
            "ks",
            "nopad",
            "mysql500",
            "400",
            "520",
            "0900",
            "1400",
            "uca1400",
            "w2",
            "pb",
            "icelandic",
            "latvian",
            "romanian",
            "slovenian",
            "polish",
            "estonian",
            "spanish",
            "spanish2",
            "swedish",
            "turkish",
            "czech",
            "danish",
            "lithuanian",
            "slovak",
            "roman",
            "persian",
            "esperanto",
            "hungarian",
            "sinhala",
            "german1",
            "german2",
            "croatian",
            "vietnamese",
            "myanmar",
            "thai",
            "ja",
            "zh",
            "ru",
            "de",
            "la",
            "hr",
            "da",
            "eo",
            "et",
            "hu",
            "is",
            "lt",
            "lv",
            "pl",
            "ro",
            "sk",
            "sl",
            "es",
            "sv",
            "tr",
            "vi",
            "mn",
            "bs",
            "bg",
            "gl",
            "sr",
            "latn",
            "cyrl",
            "nb",
            "nn",
            "no",
        ];
        if !rest.split('_').all(|w| WORDS.contains(&w)) {
            return None;
        }
        if n.ends_with("_bin") || n.ends_with("_cs") {
            return Some(Collation::Utf8Bin);
        }
        if !n.ends_with("_ci") {
            return None;
        }
        let pad = !rest.contains("nopad") && !rest.starts_with("0900");
        Some(if rest.starts_with("general") {
            Collation::General { pad }
        } else if cs == "utf8mb4" || cs == "utf8mb3" || cs == "utf8" || cs == "uca1400" {
            Collation::Unicode { pad }
        } else {
            Collation::General { pad }
        })
    }

    /// Canonical name of the implemented collation.
    pub fn name(self) -> &'static str {
        match self {
            Collation::Utf8Bin => "utf8mb4_bin",
            Collation::Utf8NoPad => "utf8mb4_0900_bin",
            Collation::General { pad: true } => "utf8mb4_general_ci",
            Collation::General { pad: false } => "utf8mb4_general_nopad_ci",
            Collation::Unicode { pad: true } => "utf8mb4_unicode_ci",
            Collation::Unicode { pad: false } => "utf8mb4_unicode_nopad_ci",
            Collation::Binary => "binary",
        }
    }

    /// MySQL / MariaDB collation id (result-set metadata, handshake).
    pub fn id(self) -> u16 {
        match self {
            Collation::Utf8Bin => 46,
            Collation::Utf8NoPad => 309,
            Collation::General { pad: true } => 45,
            Collation::General { pad: false } => 1069,
            Collation::Unicode { pad: true } => 224,
            Collation::Unicode { pad: false } => 1248,
            Collation::Binary => 63,
        }
    }

    /// The collation a client asks for by id in its handshake.
    pub fn from_id(id: u16) -> Option<Collation> {
        Some(match id {
            309 => Collation::Utf8NoPad,
            46 | 83 | 65 | 47 | 1070 => Collation::Utf8Bin,
            45 | 33 | 8 | 48 | 11 => Collation::General { pad: true },
            1069 | 1057 => Collation::General { pad: false },
            224 | 192 | 246 | 214 => Collation::Unicode { pad: true },
            255 | 1248 | 1270 => Collation::Unicode { pad: false },
            63 => Collation::Binary,
            _ => return None,
        })
    }

    /// Case-insensitive: compared by weights rather than bytes.
    pub fn is_ci(self) -> bool {
        matches!(self, Collation::General { .. } | Collation::Unicode { .. })
    }

    fn pad(self) -> bool {
        matches!(
            self,
            Collation::General { pad: true } | Collation::Unicode { pad: true }
        )
    }

    fn space(self) -> u16 {
        match self {
            Collation::Unicode { .. } => 0x0209,
            _ => 0x0020,
        }
    }

    /// The comparison key of a string: equal keys for equal strings, keys
    /// ordered as the strings are. For `_ci` collations the weight string
    /// (big-endian 16-bit weights, without trailing space weights under PAD
    /// SPACE); otherwise the bytes themselves.
    pub fn key(self, s: &[u8]) -> Bytes {
        if !self.is_ci() {
            return Bytes::copy_from_slice(s);
        }
        let mut w = Vec::with_capacity(s.len() * 2);
        for_each_weight(self, s, |x| w.push(x));
        if self.pad() {
            let sp = self.space();
            while w.last() == Some(&sp) {
                w.pop();
            }
        }
        let mut out = Vec::with_capacity(w.len() * 2);
        for x in w {
            out.extend_from_slice(&x.to_be_bytes());
        }
        Bytes::from(out)
    }

    /// WEIGHT_STRING(s) as MariaDB returns it (trailing spaces included):
    /// 16-bit weights for `_ci` collations, 24-bit code points for
    /// utf8mb4_bin, the bytes for binary strings.
    pub fn weight_string(self, s: &[u8]) -> Bytes {
        match self {
            Collation::Binary | Collation::Utf8NoPad => Bytes::copy_from_slice(s),
            Collation::Utf8Bin => {
                let mut out = Vec::with_capacity(s.len() * 3);
                for c in String::from_utf8_lossy(s).chars() {
                    out.extend_from_slice(&(c as u32).to_be_bytes()[1..]);
                }
                Bytes::from(out)
            }
            _ => {
                let mut out = Vec::with_capacity(s.len() * 2);
                for_each_weight(self, s, |x| out.extend_from_slice(&x.to_be_bytes()));
                Bytes::from(out)
            }
        }
    }

    pub fn cmp(self, a: &[u8], b: &[u8]) -> Ordering {
        if !self.is_ci() {
            return a.cmp(b);
        }
        if a.is_ascii() && b.is_ascii() && self.ascii_simple() {
            return self.cmp_ascii(a, b);
        }
        self.key(a).cmp(&self.key(b))
    }

    pub fn eq(self, a: &[u8], b: &[u8]) -> bool {
        self.cmp(a, b) == Ordering::Equal
    }

    /// For ASCII text every character has one weight (general_ci: the
    /// upper-case letter; unicode_ci: a table lookup with no ignorables
    /// among printable characters) -- the common case, compared without
    /// building keys.
    fn ascii_simple(self) -> bool {
        matches!(self, Collation::General { .. })
    }

    fn cmp_ascii(self, a: &[u8], b: &[u8]) -> Ordering {
        // As the keys: without trailing spaces under PAD SPACE, then
        // upper-case bytes, a prefix first.
        let trim = |s: &[u8]| -> usize {
            if self.pad() {
                s.iter().rposition(|&c| c != b' ').map_or(0, |i| i + 1)
            } else {
                s.len()
            }
        };
        let (a, b) = (&a[..trim(a)], &b[..trim(b)]);
        for (x, y) in a.iter().zip(b) {
            let (x, y) = (x.to_ascii_uppercase(), y.to_ascii_uppercase());
            if x != y {
                return x.cmp(&y);
            }
        }
        a.len().cmp(&b.len())
    }

    /// `s LIKE p` (`%`, `_`, `\` escapes): characters match by their
    /// weights under `_ci` collations, by bytes otherwise. No padding.
    pub fn like(self, s: &[u8], p: &[u8]) -> bool {
        if !self.is_ci() {
            return crate::expr::like_match(s, p);
        }
        let sc: Vec<char> = String::from_utf8_lossy(s).chars().collect();
        let pc: Vec<char> = String::from_utf8_lossy(p).chars().collect();
        let same = |a: char, b: char| a == b || self.char_eq(a, b);
        let (mut si, mut pi) = (0usize, 0usize);
        let (mut star_p, mut star_s) = (usize::MAX, 0usize);
        while si < sc.len() {
            if pi < pc.len() && pc[pi] == '\\' && pi + 1 < pc.len() {
                if same(sc[si], pc[pi + 1]) {
                    si += 1;
                    pi += 2;
                    continue;
                }
            } else if pi < pc.len() && pc[pi] == '%' {
                star_p = pi;
                star_s = si;
                pi += 1;
                continue;
            } else if pi < pc.len() && (pc[pi] == '_' || same(sc[si], pc[pi])) {
                si += 1;
                pi += 1;
                continue;
            }
            if star_p != usize::MAX {
                pi = star_p + 1;
                star_s += 1;
                si = star_s;
                continue;
            }
            return false;
        }
        while pi < pc.len() && pc[pi] == '%' {
            pi += 1;
        }
        pi == pc.len()
    }

    fn char_eq(self, a: char, b: char) -> bool {
        let mut x = Vec::new();
        let mut y = Vec::new();
        char_weights(self, a as u32, &mut |w| x.push(w));
        char_weights(self, b as u32, &mut |w| y.push(w));
        x == y
    }

    /// LOCATE(needle, hay): 1-based character position of the first match,
    /// 0 if none. Under `_ci` collations, as MariaDB: at each character of
    /// `hay`, the bytes as long as `needle` compare equal to it (so `'ss'`
    /// finds `'ß'` under utf8mb4_unicode_ci).
    pub fn locate(self, needle: &[u8], hay: &[u8]) -> i64 {
        if needle.is_empty() {
            return 1;
        }
        let hs = String::from_utf8_lossy(hay);
        let ns = String::from_utf8_lossy(needle);
        if !self.is_ci() {
            return hs.find(&*ns).map(|i| hs[..i].chars().count() as i64 + 1).unwrap_or(0);
        }
        let (hb, nb) = (hs.as_bytes(), ns.as_bytes());
        let want = self.weight_string(nb);
        for (k, (i, _)) in hs.char_indices().enumerate() {
            if i + nb.len() > hb.len() {
                break;
            }
            if self.weight_string(&hb[i..i + nb.len()]) == want {
                return k as i64 + 1;
            }
        }
        0
    }
}

/// Call `f` with every weight of `s` in order.
fn for_each_weight(coll: Collation, s: &[u8], mut f: impl FnMut(u16)) {
    match std::str::from_utf8(s) {
        Ok(t) => {
            for c in t.chars() {
                char_weights(coll, c as u32, &mut f);
            }
        }
        Err(_) => {
            for c in String::from_utf8_lossy(s).chars() {
                char_weights(coll, c as u32, &mut f);
            }
        }
    }
}

fn char_weights(coll: Collation, cp: u32, f: &mut impl FnMut(u16)) {
    if cp > 0xFFFF {
        f(0xFFFD);
        return;
    }
    match coll {
        Collation::General { .. } => f(general_table()[cp as usize]),
        Collation::Unicode { .. } => {
            let e = unicode_table()[cp as usize];
            if e == IMPLICIT {
                let base = if (0x4E00..=0x9FA5).contains(&cp) || FB40_EXTRA.contains(&cp) {
                    0xFB40
                } else if (0x3400..=0x4DB5).contains(&cp) {
                    0xFB80
                } else {
                    0xFBC0
                };
                f((base + (cp >> 15)) as u16);
                f(((cp & 0x7FFF) | 0x8000) as u16);
            } else {
                let (off, n) = ((e >> 8) as usize, (e & 0xFF) as usize);
                for &w in &data::UNICODE_CI_WEIGHTS[off..off + n] {
                    f(w);
                }
            }
        }
        _ => {}
    }
}

/// Compatibility ideographs that UCA 4.0.0 weighs like unified ones.
const FB40_EXTRA: [u32; 12] = [
    0xFA0E, 0xFA0F, 0xFA11, 0xFA13, 0xFA14, 0xFA1F, 0xFA21, 0xFA23, 0xFA24, 0xFA27, 0xFA28, 0xFA29,
];

const IMPLICIT: u32 = u32::MAX;

fn general_table() -> &'static [u16] {
    static T: OnceLock<Vec<u16>> = OnceLock::new();
    T.get_or_init(|| {
        let mut t: Vec<u16> = (0..=0xFFFFu32).map(|c| c as u16).collect();
        for &(c, w) in data::GENERAL_CI.iter() {
            t[c as usize] = w;
        }
        t
    })
}

/// Per BMP code point: (offset << 8 | count) into UNICODE_CI_WEIGHTS, or
/// IMPLICIT.
fn unicode_table() -> &'static [u32] {
    static T: OnceLock<Vec<u32>> = OnceLock::new();
    T.get_or_init(|| {
        let mut t = vec![IMPLICIT; 0x10000];
        for &(c, off, n) in data::UNICODE_CI_INDEX.iter() {
            t[c as usize] = ((off as u32) << 8) | n as u32;
        }
        t
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    const G: Collation = Collation::General { pad: true };
    const GN: Collation = Collation::General { pad: false };
    const U: Collation = Collation::Unicode { pad: true };
    const UN: Collation = Collation::Unicode { pad: false };

    fn hex(b: &[u8]) -> String {
        b.iter().map(|x| format!("{:02X}", x)).collect()
    }

    #[test]
    fn weight_strings_match_mariadb() {
        // SELECT HEX(WEIGHT_STRING(_utf8mb4'aB ß_é😀 ' COLLATE ...)) on MariaDB 10.11
        let s = "aB ß_é😀 ".as_bytes();
        assert_eq!(hex(&G.weight_string(s)), "0041004200200053005F0045FFFD0020");
        assert_eq!(hex(&U.weight_string(s)), "0E330E4A02090FEA0FEA021B0E8BFFFD0209");
        assert_eq!(
            hex(&Collation::Utf8Bin.weight_string(s)),
            "0000610000420000200000DF00005F0000E901F600000020"
        );
        assert_eq!(hex(&U.weight_string("中".as_bytes())), "FB40CE2D");
        assert_eq!(hex(&U.weight_string("가".as_bytes())), "FBC1AC00");
        assert_eq!(hex(&U.weight_string(b"a\0")), "0E33");
        assert_eq!(hex(&U.weight_string("あア".as_bytes())), "1E521E52");
    }

    #[test]
    fn ascii_general_weights_are_upper_case() {
        for c in 0u8..128 {
            assert_eq!(general_table()[c as usize], c.to_ascii_uppercase() as u16, "{}", c);
        }
    }

    #[test]
    fn equality_and_padding() {
        assert!(G.eq(b"Alice", b"aLICE"));
        assert!(G.eq("é".as_bytes(), b"E"));
        assert!(G.eq("ß".as_bytes(), b"s"));
        assert!(!G.eq("ß".as_bytes(), b"ss"));
        assert!(U.eq("ß".as_bytes(), b"ss"));
        assert!(U.eq("œ".as_bytes(), b"OE"));
        assert!(U.eq("ﬁ".as_bytes(), b"fi"));
        assert!(!U.eq("Æ".as_bytes(), b"ae")); // a letter of its own in UCA 4.0.0
        assert!(G.eq("😀".as_bytes(), "😁".as_bytes()));
        assert!(G.eq(b"a", b"a  "));
        assert!(!GN.eq(b"a", b"a  "));
        assert!(U.eq(b"a", "a \u{a0}".as_bytes()));
        assert!(!UN.eq(b"a", b"a "));
        assert!(!Collation::Utf8Bin.eq(b"a", b"A"));
        assert_eq!(G.key(b"ab  "), G.key(b"AB"));
        assert_ne!(GN.key(b"ab  "), GN.key(b"AB"));
    }

    #[test]
    fn ordering_follows_keys() {
        // general_ci: by upper-case code points ('_' after letters)
        assert_eq!(G.cmp(b"ab", b"a_b"), Ordering::Less);
        assert_eq!(U.cmp(b"ab", b"a_b"), Ordering::Greater);
        assert_eq!(G.cmp(b"apple", b"Banana"), Ordering::Less);
        assert_eq!(Collation::Utf8Bin.cmp(b"apple", b"Banana"), Ordering::Greater);
        // the ASCII fast path agrees with the keys
        let words: [&[u8]; 9] = [b"", b" ", b"a", b"a ", b"A b", b"a\t", b"ab", b"a_b", b"Zz"];
        for c in [G, GN] {
            for x in words {
                for y in words {
                    assert_eq!(c.cmp_ascii(x, y), c.key(x).cmp(&c.key(y)), "{:?} {:?}", x, y);
                }
            }
        }
    }

    #[test]
    fn like_by_weights() {
        assert!(G.like(b"abc", b"AB_"));
        assert!(G.like("ßx".as_bytes(), b"s%"));
        assert!(!U.like("ß".as_bytes(), b"s"));
        assert!(!U.like("ß".as_bytes(), b"ss"));
        assert!(U.like("Ébène".as_bytes(), b"eb%NE"));
        assert!(!G.like(b"a ", b"a"));
        assert!(G.like(b"50%", b"50\\%"));
        assert!(!Collation::Utf8Bin.like(b"abc", b"AB_"));
    }

    #[test]
    fn locate_like_mariadb() {
        assert_eq!(G.locate(b"B", b"abc"), 2);
        assert_eq!(U.locate(b"ss", "aßc".as_bytes()), 2);
        assert_eq!(G.locate(b"s", "aßc".as_bytes()), 0);
        assert_eq!(Collation::Utf8Bin.locate(b"b", b"ABC"), 0);
        assert_eq!(G.locate(b"", b"abc"), 1);
    }

    #[test]
    fn names_and_aggregation() {
        assert_eq!(Collation::from_name("utf8mb4_general_ci"), Some(G));
        assert_eq!(Collation::from_name("UTF8_GENERAL_CI"), Some(G));
        assert_eq!(Collation::from_name("utf8mb4_0900_ai_ci"), Some(UN));
        assert_eq!(Collation::from_name("utf8mb4_unicode_520_ci"), Some(U));
        assert_eq!(Collation::from_name("utf8mb4_0900_as_cs"), Some(Collation::Utf8Bin));
        assert_eq!(Collation::from_name("latin1_swedish_ci"), Some(G));
        assert_eq!(Collation::from_name("klingon_ci"), None);
        assert_eq!(Collation::from_name("utf8mb4_nonesuch_ci"), None);
        assert_eq!(Collation::from_name("utf8mb4_german2_ci"), Some(U));
        assert_eq!(Collation::from_name("utf8mb4_uca1400_swedish_nopad_ai_ci"), Some(UN));
        let d = |c, k| Some(Derived::new(c, k));
        use coercibility::*;
        let r = aggregate(&[d(G, IMPLICIT), d(Collation::Utf8Bin, COERCIBLE)], "=").unwrap();
        assert_eq!(r.unwrap().coll, G);
        let r = aggregate(&[d(G, IMPLICIT), d(Collation::Utf8Bin, IMPLICIT)], "=").unwrap();
        assert_eq!(r.unwrap().coll, Collation::Utf8Bin);
        assert_eq!(
            aggregate(&[d(G, IMPLICIT), d(U, IMPLICIT)], "=").unwrap_err().code,
            1267
        );
        assert_eq!(
            aggregate(&[d(G, EXPLICIT), d(U, IMPLICIT)], "=").unwrap().unwrap().coll,
            G
        );
        assert_eq!(aggregate(&[None, None], "=").unwrap(), None);
        // a binary string wins at a tie only (#122): over a coercible
        // literal, not over a column or an explicit collation
        let bin = |k| d(Collation::Binary, k);
        assert_eq!(
            aggregate(&[bin(COERCIBLE), d(G, COERCIBLE)], "=")
                .unwrap()
                .unwrap()
                .coll,
            Collation::Binary
        );
        assert_eq!(
            aggregate(&[d(G, IMPLICIT), bin(IMPLICIT)], "=").unwrap().unwrap().coll,
            Collation::Binary
        );
        assert_eq!(
            aggregate(&[d(G, IMPLICIT), bin(COERCIBLE)], "=").unwrap().unwrap().coll,
            G
        );
        assert_eq!(
            aggregate(&[bin(IMPLICIT), d(G, EXPLICIT)], "=").unwrap().unwrap().coll,
            G
        );
    }
}
